INSERT INTO "daily_sets" ("id", "owner_id", "name", "built_in") VALUES ('6f1a2b3c-0003-4000-8000-000000000003', NULL, 'Daily Verse', true) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
INSERT INTO "daily_lines" ("set_id", "text", "position", "reading_date") VALUES
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Then he said to them, “The harvest is indeed plentiful, but the laborers are few. Pray therefore to the Lord of the harvest, that he may send out laborers into his harvest.” Luke 10:2', 0, '2026-10-01'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Whoever therefore humbles himself as this little child, the same is the greatest in the Kingdom of Heaven. Matthew 18:4', 1, '2026-10-02'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Nevertheless, don’t rejoice in this, that the spirits are subject to you, but rejoice that your names are written in heaven. Luke 10:20', 2, '2026-10-03'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Jesus said to them, “Did you never read in the Scriptures, ‘The stone which the builders rejected, the same was made the head of the corner. This was from the Lord. It is marvelous in our eyes?’” Matthew 21:42', 3, '2026-10-04'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He said, “He who showed mercy on him.” Then Jesus said to him, “Go and do likewise.” Luke 10:37', 4, '2026-10-05'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Jesus answered her, “Martha, Martha, you are anxious and troubled about many things, but one thing is needed. Mary has chosen the good part, which will not be taken away from her.” Luke 10:41-42', 5, '2026-10-06'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'When he finished praying in a certain place, one of his disciples said to him, “Lord, teach us to pray, just as John also taught his disciples.” Luke 11:1', 6, '2026-10-07'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'I tell you, keep asking, and it will be given you. Keep seeking, and you will find. Keep knocking, and it will be opened to you. Luke 11:9', 7, '2026-10-08'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'But if I by God’s finger cast out demons, then God’s Kingdom has come to you. Luke 11:20', 8, '2026-10-09'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'But he said, “On the contrary, blessed are those who hear the word of God, and keep it.” Luke 11:28', 9, '2026-10-10'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'For many are called, but few chosen. Matthew 22:14', 10, '2026-10-11'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'For even as Jonah became a sign to the Ninevites, so will also the Son of Man be to this generation. Luke 11:30', 11, '2026-10-12'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'But give for gifts to the needy those things which are within, and behold, all things will be clean to you. Luke 11:41', 12, '2026-10-13'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'But woe to you Pharisees! For you tithe mint and rue and every herb, but you bypass justice and God’s love. You ought to have done these, and not to have left the other undone. Luke 11:42', 13, '2026-10-14'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Woe to you lawyers! For you took away the key of knowledge. You didn’t enter in yourselves, and those who were entering in, you hindered. Luke 11:52', 14, '2026-10-15'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'But the very hairs of your head are all counted. Therefore don’t be afraid. You are of more value than many sparrows. Luke 12:7', 15, '2026-10-16'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'For the Holy Spirit will teach you in that same hour what you must say. Luke 12:12', 16, '2026-10-17'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'They said to him, “Caesar’s.” Then he said to them, “Give therefore to Caesar the things that are Caesar’s, and to God the things that are God’s.” Matthew 22:21', 17, '2026-10-18'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He said to them, “Beware! Keep yourselves from covetousness, for a man’s life doesn’t consist of the abundance of the things which he possesses.” Luke 12:15', 18, '2026-10-19'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Let your waist be dressed and your lamps burning. Luke 12:35', 19, '2026-10-20'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Therefore be ready also, for the Son of Man is coming in an hour that you don’t expect him. Luke 12:40', 20, '2026-10-21'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'I came to throw fire on the earth. I wish it were already kindled. Luke 12:49', 21, '2026-10-22'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Why don’t you judge for yourselves what is right? Luke 12:57', 22, '2026-10-23'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He answered, ‘Lord, leave it alone this year also, until I dig around it, and fertilize it. Luke 13:8', 23, '2026-10-24'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Jesus said to him, “‘You shall love the Lord your God with all your heart, with all your soul, and with all your mind.’” Matthew 22:37', 24, '2026-10-25'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'When Jesus saw her, he called her, and said to her, “Woman, you are freed from your infirmity.” Luke 13:12', 25, '2026-10-26'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'It is like a grain of mustard seed, which a man took, and put in his own garden. It grew, and became a large tree, and the birds of the sky live in its branches. Luke 13:19', 26, '2026-10-27'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'In these days, he went out to the mountain to pray, and he continued all night in prayer to God. Luke 6:12', 27, '2026-10-28'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Jerusalem, Jerusalem, that kills the prophets, and stones those who are sent to her! How often I wanted to gather your children together, like a hen gathers her own brood under her wings, and you refused! Luke 13:34', 28, '2026-10-29'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He answered them, “Which of you, if your son or an ox fell into a well, wouldn’t immediately pull him out on a Sabbath day?” Luke 14:5', 29, '2026-10-30'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'For everyone who exalts himself will be humbled, and whoever humbles himself will be exalted. Luke 14:11', 30, '2026-10-31'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Blessed are those who hunger and thirst after righteousness, for they shall be filled. Matthew 5:6', 31, '2026-11-01'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'All those whom the Father gives me will come to me. He who comes to me I will in no way throw out. John 6:37', 32, '2026-11-02'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He sent out his servant at supper time to tell those who were invited, ‘Come, for everything is ready now.’ Luke 14:17', 33, '2026-11-03'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'For which of you, desiring to build a tower, doesn’t first sit down and count the cost, to see if he has enough to complete it? Luke 14:28', 34, '2026-11-04'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Even so, I tell you, there is joy in the presence of the angels of God over one sinner repenting. Luke 15:10', 35, '2026-11-05'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'His lord commended the dishonest manager because he had done wisely, for the children of this world are, in their own generation, wiser than the children of the light. Luke 16:8', 36, '2026-11-06'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He who is faithful in a very little is faithful also in much. He who is dishonest in a very little is also dishonest in much. Luke 16:10', 37, '2026-11-07'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Watch therefore, for you don’t know the day nor the hour in which the Son of Man is coming. Matthew 25:13', 38, '2026-11-08'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Jesus answered them, “Destroy this temple, and in three days I will raise it up.” John 2:19', 39, '2026-11-09'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Even so you also, when you have done all the things that are commanded you, say, ‘We are unworthy servants. We have done our duty.’ Luke 17:10', 40, '2026-11-10'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Then he said to him, “Get up, and go your way. Your faith has healed you.” Luke 17:19', 41, '2026-11-11'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Neither will they say, ‘Look, here!’ or, ‘Look, there!’ for behold, God’s Kingdom is within you. Luke 17:21', 42, '2026-11-12'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Whoever seeks to save his life loses it, but whoever loses his life preserves it. Luke 17:33', 43, '2026-11-13'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Won’t God avenge his chosen ones, who are crying out to him day and night, and yet he exercises patience with them? Luke 18:7', 44, '2026-11-14'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'His lord said to him, ‘Well done, good and faithful servant. You have been faithful over a few things, I will set you over many things. Enter into the joy of your lord.’ Matthew 25:21', 45, '2026-11-15'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Jesus said to him, “Receive your sight. Your faith has healed you.” Luke 18:42', 46, '2026-11-16'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'For the Son of Man came to seek and to save that which was lost. Luke 19:10', 47, '2026-11-17'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He said to him, ‘Well done, you good servant! Because you were found faithful with very little, you shall have authority over ten cities.’ Luke 19:17', 48, '2026-11-18'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Saying, “If you, even you, had known today the things which belong to your peace! But now, they are hidden from your eyes.” Luke 19:42', 49, '2026-11-19'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Saying to them, “It is written, ‘My house is a house of prayer,’ but you have made it a ‘den of robbers’!” Luke 19:46', 50, '2026-11-20'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Now he is not the God of the dead, but of the living, for all are alive to him. Luke 20:38', 51, '2026-11-21'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'The King will answer them, ‘Most certainly I tell you, because you did it to one of the least of these my brothers, you did it to me.’ Matthew 25:40', 52, '2026-11-22'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He said, “Truly I tell you, this poor widow put in more than all of them, for all these put in gifts for God from their abundance, but she, out of her poverty, put in all that she had to live on.” Luke 21:3-4', 53, '2026-11-23'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'When you hear of wars and disturbances, don’t be terrified, for these things must happen first, but the end won’t come immediately. Luke 21:9', 54, '2026-11-24'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'By your endurance you will win your lives. Luke 21:19', 55, '2026-11-25'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He fell on his face at Jesus’ feet, giving him thanks; and he was a Samaritan. Luke 17:16', 56, '2026-11-26'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Heaven and earth will pass away, but my words will by no means pass away. Luke 21:33', 57, '2026-11-27'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Therefore be watchful all the time, praying that you may be counted worthy to escape all these things that will happen, and to stand before the Son of Man. Luke 21:36', 58, '2026-11-28'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Watch, keep alert, and pray; for you don’t know when the time is. Mark 13:33', 59, '2026-11-29'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He said to them, “Come after me, and I will make you fishers for men.” Matthew 4:19', 60, '2026-11-30'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Turning to the disciples, he said, “All things have been delivered to me by my Father. No one knows who the Son is, except the Father, and who the Father is, except the Son, and he to whomever the Son desires to reveal him.” Luke 10:22', 61, '2026-12-01'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'They all ate, and were filled. They took up seven baskets full of the broken pieces that were left over. Matthew 15:37', 62, '2026-12-02'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Everyone therefore who hears these words of mine, and does them, I will liken him to a wise man, who built his house on a rock. Matthew 7:24', 63, '2026-12-03'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Then he touched their eyes, saying, “According to your faith be it done to you.” Matthew 9:29', 64, '2026-12-04'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'But when he saw the multitudes, he was moved with compassion for them, because they were harassed and scattered, like sheep without a shepherd. Matthew 9:36', 65, '2026-12-05'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'The voice of one crying in the wilderness, ‘Make ready the way of the Lord! Make his paths straight!’ Mark 1:3', 66, '2026-12-06'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Seeing their faith, he said to him, “Man, your sins are forgiven you.” Luke 5:20', 67, '2026-12-07'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'For nothing spoken by God is impossible. Luke 1:37', 68, '2026-12-08'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Come to me, all you who labor and are heavily burdened, and I will give you rest. Matthew 11:28', 69, '2026-12-09'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He who has ears to hear, let him hear. Matthew 11:15', 70, '2026-12-10'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'The Son of Man came eating and drinking, and they say, ‘Behold, a gluttonous man and a drunkard, a friend of tax collectors and sinners!’ But wisdom is justified by her children. Matthew 11:19', 71, '2026-12-11'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Mary said, “Behold, the servant of the Lord; let it be done to me according to your word.” The angel departed from her. Luke 1:38', 72, '2026-12-12'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He was not the light, but was sent that he might testify about the light. John 1:8', 73, '2026-12-13'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Jesus answered them, “I also will ask you one question, which if you tell me, I likewise will tell you by what authority I do these things.” Matthew 21:24', 74, '2026-12-14'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He answered, ‘I will not,’ but afterward he changed his mind, and went. Matthew 21:29', 75, '2026-12-15'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Blessed is he who finds no occasion for stumbling in me. Luke 7:23', 76, '2026-12-16'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Jacob became the father of Joseph, the husband of Mary, from whom was born Jesus, who is called Christ. Matthew 1:16', 77, '2026-12-17'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'She shall give birth to a son. You shall call his name Jesus, for it is he who shall save his people from their sins. Matthew 1:21', 78, '2026-12-18'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'But the angel said to him, “Don’t be afraid, Zacharias, because your request has been heard, and your wife, Elizabeth, will bear you a son, and you shall call his name John.” Luke 1:13', 79, '2026-12-19'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'The angel said to her, “Don’t be afraid, Mary, for you have found favor with God.” Luke 1:30', 80, '2026-12-20'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Blessed is she who believed, for there will be a fulfillment of the things which have been spoken to her from the Lord! Luke 1:45', 81, '2026-12-21'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'For he who is mighty has done great things for me. Holy is his name. Luke 1:49', 82, '2026-12-22'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'All who heard them laid them up in their heart, saying, “What then will this child be?” The hand of the Lord was with him. Luke 1:66', 83, '2026-12-23'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'To shine on those who sit in darkness and the shadow of death; to guide our feet into the way of peace. Luke 1:79', 84, '2026-12-24'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'The light shines in the darkness, and the darkness hasn’t overcome it. John 1:5', 85, '2026-12-25'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'But when they deliver you up, don’t be anxious how or what you will say, for it will be given you in that hour what you will say. Matthew 10:19', 86, '2026-12-26'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'The child was growing, and was becoming strong in spirit, being filled with wisdom, and the grace of God was upon him. Luke 2:40', 87, '2026-12-27'),
  ('6f1a2b3c-0003-4000-8000-000000000003', '“A voice was heard in Ramah, lamentation, weeping and great mourning, Rachel weeping for her children; she wouldn’t be comforted, because they are no more.” Matthew 2:18', 88, '2026-12-28'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'A light for revelation to the nations, and the glory of your people Israel. Luke 2:32', 89, '2026-12-29'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Coming up at that very hour, she gave thanks to the Lord, and spoke of him to all those who were looking for redemption in Jerusalem. Luke 2:38', 90, '2026-12-30'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'The Word became flesh, and lived among us. We saw his glory, such glory as of the one and only Son of the Father, full of grace and truth. John 1:14', 91, '2026-12-31'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'But Mary kept all these sayings, pondering them in her heart. Luke 2:19', 92, '2027-01-01'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He said, “I am the voice of one crying in the wilderness, ‘Make straight the way of the Lord,’ as Isaiah the prophet said.” John 1:23', 93, '2027-01-02'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'When they saw the star, they rejoiced with exceedingly great joy. Matthew 2:10', 94, '2027-01-03'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'The people who sat in darkness saw a great light, to those who sat in the region and shadow of death, to them light has dawned. Matthew 4:16', 95, '2027-01-04'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Jesus came out, saw a great multitude, and he had compassion on them, because they were like sheep without a shepherd, and he began to teach them many things. Mark 6:34', 96, '2027-01-05'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'For they all saw him, and were troubled. But he immediately spoke with them, and said to them, “Cheer up! It is I! Don’t be afraid.” Mark 6:50', 97, '2027-01-06'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He began to tell them, “Today, this Scripture has been fulfilled in your hearing.” Luke 4:21', 98, '2027-01-07'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'But he withdrew himself into the desert, and prayed. Luke 5:16', 99, '2027-01-08'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He must increase, but I must decrease. John 3:30', 100, '2027-01-09'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'A voice came out of the sky, “You are my beloved Son, in whom I am well pleased.” Mark 1:11', 101, '2027-01-10'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'And saying, “The time is fulfilled, and God’s Kingdom is at hand! Repent, and believe in the Good News.” Mark 1:15', 102, '2027-01-11'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'They were astonished at his teaching, for he taught them as having authority, and not as the scribes. Mark 1:22', 103, '2027-01-12'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Early in the morning, while it was still dark, he rose up and went out, and departed into a deserted place, and prayed there. Mark 1:35', 104, '2027-01-13'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Being moved with compassion, he stretched out his hand, and touched him, and said to him, “I want to. Be made clean.” Mark 1:41', 105, '2027-01-14'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Jesus, seeing their faith, said to the paralytic, “Son, your sins are forgiven you.” Mark 2:5', 106, '2027-01-15'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'When Jesus heard it, he said to them, “Those who are healthy have no need for a physician, but those who are sick. I came not to call the righteous, but sinners to repentance.” Mark 2:17', 107, '2027-01-16'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He said to them, “Come, and see.” They came and saw where he was staying, and they stayed with him that day. It was about the tenth hour. John 1:39', 108, '2027-01-17'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'No one puts new wine into old wineskins, or else the new wine will burst the skins, and the wine pours out, and the skins will be destroyed; but they put new wine into fresh wineskins. Mark 2:22', 109, '2027-01-18'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He said to them, “The Sabbath was made for man, not man for the Sabbath.” Mark 2:27', 110, '2027-01-19'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He said to them, “Is it lawful on the Sabbath day to do good, or to do harm? To save a life, or to kill?” But they were silent. Mark 3:4', 111, '2027-01-20'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'For he had healed many, so that as many as had diseases pressed on him that they might touch him. Mark 3:10', 112, '2027-01-21'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He went up into the mountain, and called to himself those whom he wanted, and they went to him. Mark 3:13', 113, '2027-01-22'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'The multitude came together again, so that they could not so much as eat bread. Mark 3:20', 114, '2027-01-23'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Jesus said to them, “Come after me, and I will make you into fishers for men.” Mark 1:17', 115, '2027-01-24'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He said to them, “Go into all the world, and preach the Good News to the whole creation.” Mark 16:15', 116, '2027-01-25'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'For whoever does the will of God, the same is my brother, and my sister, and mother. Mark 3:35', 117, '2027-01-26'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Those which were sown on the good ground are those who hear the word, and accept it, and bear fruit, some thirty times, some sixty times, and some one hundred times. Mark 4:20', 118, '2027-01-27'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He said to them, “Take heed what you hear. With whatever measure you measure, it will be measured to you, and more will be given to you who hear.” Mark 4:24', 119, '2027-01-28'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'For the earth bears fruit: first the blade, then the ear, then the full grain in the ear. Mark 4:28', 120, '2027-01-29'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He said to them, “Why are you so afraid? How is it that you have no faith?” Mark 4:40', 121, '2027-01-30'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'They were all amazed, so that they questioned among themselves, saying, “What is this? A new teaching? For with authority he commands even the unclean spirits, and they obey him!” Mark 1:27', 122, '2027-01-31'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He didn’t allow him, but said to him, “Go to your house, to your friends, and tell them what great things the Lord has done for you, and how he had mercy on you.” Mark 5:19', 123, '2027-02-01'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Now you are releasing your servant, Master, according to your word, in peace. Luke 2:29', 124, '2027-02-02'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Jesus said to them, “A prophet is not without honor, except in his own country, and among his own relatives, and in his own house.” Mark 6:4', 125, '2027-02-03'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'They cast out many demons, and anointed many with oil who were sick, and healed them. Mark 6:13', 126, '2027-02-04'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'For Herod feared John, knowing that he was a righteous and holy man, and kept him safe. When he heard him, he did many things, and he heard him gladly. Mark 6:20', 127, '2027-02-05'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He said to them, “You come apart into a deserted place, and rest awhile.” For there were many coming and going, and they had no leisure so much as to eat. Mark 6:31', 128, '2027-02-06'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He came and took her by the hand, and raised her up. The fever left her, and she served them. Mark 1:31', 129, '2027-02-07'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'And ran around that whole region, and began to bring those who were sick, on their mats, to where they heard he was. Mark 6:55', 130, '2027-02-08'),
  ('6f1a2b3c-0003-4000-8000-000000000003', '“For you set aside the commandment of God, and hold tightly to the tradition of men—the washing of pitchers and cups, and you do many other such things.” Mark 7:8', 131, '2027-02-09'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'But you, when you pray, enter into your inner room, and having shut your door, pray to your Father who is in secret, and your Father who sees in secret will reward you openly. Matthew 6:6', 132, '2027-02-10'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'For what does it profit a man if he gains the whole world, and loses or forfeits his own self? Luke 9:25', 133, '2027-02-11'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Jesus said to them, “Can the friends of the bridegroom mourn, as long as the bridegroom is with them? But the days will come when the bridegroom will be taken away from them, and then they will fast.” Matthew 9:15', 134, '2027-02-12'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He left everything, and rose up and followed him. Luke 5:28', 135, '2027-02-13'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He was there in the wilderness forty days tempted by Satan. He was with the wild animals; and the angels were serving him. Mark 1:13', 136, '2027-02-14'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'For I was hungry, and you gave me food to eat. I was thirsty, and you gave me drink. I was a stranger, and you took me in. Matthew 25:35', 137, '2027-02-15'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Therefore don’t be like them, for your Father knows what things you need, before you ask him. Matthew 6:8', 138, '2027-02-16'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'The men of Nineveh will stand up in the judgment with this generation, and will condemn it: for they repented at the preaching of Jonah, and behold, one greater than Jonah is here. Luke 11:32', 139, '2027-02-17'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Ask, and it will be given you. Seek, and you will find. Knock, and it will be opened for you. Matthew 7:7', 140, '2027-02-18'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Leave your gift there before the altar, and go your way. First be reconciled to your brother, and then come and offer your gift. Matthew 5:24', 141, '2027-02-19'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'But I tell you, love your enemies, bless those who curse you, do good to those who hate you, and pray for those who mistreat you and persecute you. Matthew 5:44', 142, '2027-02-20'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'A cloud came, overshadowing them, and a voice came out of the cloud, “This is my beloved Son. Listen to him.” Mark 9:7', 143, '2027-02-21'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Simon Peter answered, “You are the Christ, the Son of the living God.” Matthew 16:16', 144, '2027-02-22'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'But he who is greatest among you will be your servant. Matthew 23:11', 145, '2027-02-23'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Even as the Son of Man came not to be served, but to serve, and to give his life as a ransom for many. Matthew 20:28', 146, '2027-02-24'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'But Abraham said to him, ‘They have Moses and the prophets. Let them listen to them.’ Luke 16:29', 147, '2027-02-25'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'But afterward he sent to them his son, saying, ‘They will respect my son.’ Matthew 21:37', 148, '2027-02-26'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He arose, and came to his father. But while he was still far off, his father saw him, and was moved with compassion, and ran, and fell on his neck, and kissed him. Luke 15:20', 149, '2027-02-27'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'His disciples remembered that it was written, “Zeal for your house will eat me up.” John 2:17', 150, '2027-02-28'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'But he, passing through the middle of them, went his way. Luke 4:30', 151, '2027-03-01'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Jesus said to him, “I don’t tell you until seven times, but, until seventy times seven.” Matthew 18:22', 152, '2027-03-02'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Don’t think that I came to destroy the law or the prophets. I didn’t come to destroy, but to fulfill. Matthew 5:17', 153, '2027-03-03'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'But he, knowing their thoughts, said to them, “Every kingdom divided against itself is brought to desolation. A house divided against itself falls.” Luke 11:17', 154, '2027-03-04'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'You shall love the Lord your God with all your heart, and with all your soul, and with all your mind, and with all your strength.’ This is the first commandment. Mark 12:30', 155, '2027-03-05'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'I tell you, this man went down to his house justified rather than the other; for everyone who exalts himself will be humbled, but he who humbles himself will be exalted. Luke 18:14', 156, '2027-03-06'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'For God so loved the world, that he gave his one and only Son, that whoever believes in him should not perish, but have eternal life. John 3:16', 157, '2027-03-07'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Jesus said to him, “Go your way. Your son lives.” The man believed the word that Jesus spoke to him, and he went his way. John 4:50', 158, '2027-03-08'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Jesus said to him, “Arise, take up your mat, and walk.” John 5:8', 159, '2027-03-09'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'But Jesus answered them, “My Father is still working, so I am working, too.” John 5:17', 160, '2027-03-10'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'You search the Scriptures, because you think that in them you have eternal life; and these are they which testify about me. John 5:39', 161, '2027-03-11'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'I know him, because I am from him, and he sent me. John 7:29', 162, '2027-03-12'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'The officers answered, “No man ever spoke like this man!” John 7:46', 163, '2027-03-13'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Most certainly I tell you, unless a grain of wheat falls into the earth and dies, it remains by itself alone. But if it dies, it bears much fruit. John 12:24', 164, '2027-03-14'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'She said, “No one, Lord.” Jesus said, “Neither do I condemn you. Go your way. From now on, sin no more.” John 8:11', 165, '2027-03-15'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He who sent me is with me. The Father hasn’t left me alone, for I always do the things that are pleasing to him. John 8:29', 166, '2027-03-16'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'You will know the truth, and the truth will make you free. John 8:32', 167, '2027-03-17'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Most certainly, I tell you, if a person keeps my word, he will never see death. John 8:51', 168, '2027-03-18'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Joseph arose from his sleep, and did as the angel of the Lord commanded him, and took his wife to himself. Matthew 1:24', 169, '2027-03-19'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'And not for the nation only, but that he might also gather together into one the children of God who are scattered abroad. John 11:52', 170, '2027-03-20'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'She has done what she could. She has anointed my body beforehand for the burying. Mark 14:8', 171, '2027-03-21'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Mary, therefore, took a pound of ointment of pure nard, very precious, and anointed the feet of Jesus, and wiped his feet with her hair. The house was filled with the fragrance of the ointment. John 12:3', 172, '2027-03-22'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'When he had gone out, Jesus said, “Now the Son of Man has been glorified, and God has been glorified in him.” John 13:31', 173, '2027-03-23'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'The disciples did as Jesus commanded them, and they prepared the Passover. Matthew 26:19', 174, '2027-03-24'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'For I have given you an example, that you also should do as I have done to you. John 13:15', 175, '2027-03-25'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'When Jesus therefore had received the vinegar, he said, “It is finished.” He bowed his head, and gave up his spirit. John 19:30', 176, '2027-03-26'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'He said to them, “Don’t be amazed. You seek Jesus, the Nazarene, who has been crucified. He has risen. He is not here. Behold, the place where they laid him!” Mark 16:6', 177, '2027-03-27'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'So then the other disciple who came first to the tomb also entered in, and he saw and believed. John 20:8', 178, '2027-03-28'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Then Jesus said to them, “Don’t be afraid. Go tell my brothers that they should go into Galilee, and there they will see me.” Matthew 28:10', 179, '2027-03-29'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Jesus said to her, “Mary.” She turned and said to him, “Rabboni!” which is to say, “Teacher!” John 20:16', 180, '2027-03-30'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'They said to one another, “Weren’t our hearts burning within us, while he spoke to us along the way, and while he opened the Scriptures to us?” Luke 24:32', 181, '2027-03-31'),
  ('6f1a2b3c-0003-4000-8000-000000000003', 'Then he opened their minds, that they might understand the Scriptures. Luke 24:45', 182, '2027-04-01');--> statement-breakpoint
